/**
 * Client-side Hybrid RAG Retriever (BM25 Sparse + Concept Expansion + Optional Cosine Similarity)
 * Reads `content/rag-index.json` generated by `scripts/build_rag_index.py`.
 */
(() => {
  let indexPromise = null;

  function normalize(value) {
    return String(value || "")
      .normalize("NFD")
      .replace(/\p{Diacritic}/gu, "")
      .replace(/ß/g, "ss")
      .replace(/ı/g, "i")
      .toLowerCase()
      .trim();
  }

  function tokenize(text) {
    return normalize(text)
      .split(/[^a-z0-9]+/)
      .filter((t) => t.length >= 2);
  }

  async function loadRagIndex(url = "content/rag-index.json") {
    if (!indexPromise) {
      indexPromise = fetch(new URL(url, document.baseURI))
        .then((res) => {
          if (!res.ok) throw new Error(`Could not load ${url}`);
          return res.json();
        })
        .catch((err) => {
          indexPromise = null;
          throw err;
        });
    }
    return indexPromise;
  }

  function expandConcepts(normalizedQuery, conceptsMap) {
    const matchedConcepts = new Set();
    const expandedTerms = new Set(tokenize(normalizedQuery));

    for (const [conceptId, terms] of Object.entries(conceptsMap || {})) {
      const normalizedTerms = terms.map(normalize);
      if (normalizedTerms.some((term) => normalizedQuery.includes(term) || expandedTerms.has(term))) {
        matchedConcepts.add(conceptId);
        normalizedTerms.forEach((term) => {
          tokenize(term).forEach((tok) => expandedTerms.add(tok));
        });
      }
    }
    return { matchedConcepts, expandedTerms: [...expandedTerms] };
  }

  async function retrieve(query, options = {}) {
    const {
      lang = null,
      sourceTypes = null,
      topK = 8,
      indexUrl = "content/rag-index.json"
    } = options;

    const index = await loadRagIndex(indexUrl);
    const normQuery = normalize(query);
    if (!normQuery) return [];

    const directTokens = tokenize(normQuery);
    const { matchedConcepts, expandedTerms } = expandConcepts(normQuery, index.concepts);

    const scored = [];
    for (const chunk of index.chunks) {
      if (sourceTypes && !sourceTypes.includes(chunk.sourceType)) continue;
      // Keep German KV chunks always eligible alongside the user's active language
      if (lang && chunk.lang !== lang && chunk.lang !== "de" && chunk.lang !== "multi") continue;

      let score = 0;

      // 1. Direct BM25 sparse dot-product
      for (const tok of directTokens) {
        if (chunk.tf && chunk.tf[tok]) {
          score += chunk.tf[tok] * 2.2;
        }
      }

      // 2. Cross-lingual concept expansion BM25 boost
      for (const tok of expandedTerms) {
        if (chunk.tf && chunk.tf[tok]) {
          score += chunk.tf[tok] * 0.65;
        }
      }

      // 3. Concept tag alignment bonus
      if (chunk.concepts) {
        for (const c of chunk.concepts) {
          if (matchedConcepts.has(c)) score += 3.5;
        }
      }

      // 4. Exact phrase match bonus
      const normTitle = normalize(chunk.title);
      if (normTitle.includes(normQuery)) score += 8.0;

      // 5. Preferred language bonus (user's language slightly boosted over fallback German)
      if (lang && chunk.lang === lang) score *= 1.15;

      if (score > 0.2) {
        scored.push({
          ...chunk,
          score: Number(score.toFixed(3))
        });
      }
    }

    scored.sort((a, b) => b.score - a.score);
    return scored.slice(0, topK);
  }

  window.haklarRAG = {
    loadRagIndex,
    retrieve
  };
})();
